import {STATUS} from './core.mjs';
import {workspaceSelect,workspaceCompare} from './app.mjs?v=1.1.0';
import {pageShell,esc,fmt,source,downloadFile} from './ocean-ui.mjs';
import {logLevel} from './ocean-data.mjs';
export function initializeRecords(){
 const {root}=pageShell('records','运行与日志','06 / RUN MISSION CONTROL','每一次运行，都保留可复核的输入、日志和结果。','<button type="button" class="ow-primary" data-page="configure">新建工况 ＋</button><span class="or-service"></span>');
 root.insertAdjacentHTML('beforeend',`<div class="or-grid"><aside class="ow-glass or-tasks"><header><h2>运行任务</h2><button type="button" class="ow-quiet" id="or-import">导入 ↗</button></header><label class="ow-search">⌕ <input type="search" id="or-task-search" placeholder="搜索工况" aria-label="搜索运行任务"></label><div class="or-task-list"></div><button type="button" class="ow-button or-backup">↓ 备份工作区</button></aside><section class="or-main"><section class="ow-glass or-workflow"><h2>求解流程</h2><ol class="or-stages"></ol><p class="or-progress-description"></p></section><section class="ow-glass or-terminal"><header><h2>运行日志</h2><div class="or-filters" role="group" aria-label="日志级别"><button type="button" data-level="all" class="active">全部</button><button type="button" data-level="info">信息</button><button type="button" data-level="warning">警告</button><button type="button" data-level="error">错误</button></div></header><div class="or-log-toolbar"><label><input type="checkbox" id="or-follow" checked> 自动跟随</label><label class="ow-search">⌕ <input id="or-log-search" type="search" placeholder="搜索日志…" aria-label="搜索日志"></label><button type="button" class="ow-quiet" id="or-paste">粘贴日志排查 ↗</button></div><div class="or-log-lines" tabindex="0" aria-label="当前工况原始日志"></div><div class="or-log-footer"></div></section></section><aside class="ow-glass or-details"><h2>当前任务</h2><div class="or-parameters"></div><h3>生成文件</h3><div class="or-artifacts"><button type="button" data-file="input"><span>▤</span><div>工况与输入清单<small>参数、来源及文件哈希 / JSON</small></div><b>↓</b></button><button type="button" data-file="log"><span>▤</span><div>原始运行日志<small>OpenFAST 日志 / .log</small></div><b>↓</b></button><button type="button" data-file="output"><span>▤</span><div>时序输出文件<small>原始 .out 或已验证的 CSV</small></div><b>↓</b></button></div><div class="or-findings"></div></aside></div><footer class="ow-page-footer"><p class="or-source-note"></p><div><button type="button" class="ow-button" id="or-results">▥ 查看结果</button><button type="button" class="ow-button" id="or-download">↓ 下载日志</button><button type="button" class="ow-danger" id="or-cancel">□ 取消运行</button></div></footer>`);
 let state=null,level='all',query='',taskQuery='',logStamp='',follow=true;
 const list=root.querySelector('.or-task-list'),lines=root.querySelector('.or-log-lines');
 function tasks(){const scroll=list.scrollTop;const filtered=(state?.runs||[]).filter(r=>r.name.toLowerCase().includes(taskQuery));list.innerHTML=['preparing','running','completed','failed','cancelled'].map(status=>{const runs=filtered.filter(r=>r.status===status);if(!runs.length)return '';return `<section><h3><i class="status-${status}"></i>${STATUS[status]} <small>(${runs.length})</small></h3>${runs.map(r=>`<article class="or-task ${state.record?.id===r.id?'selected':''}"><button type="button" data-run="${esc(r.id)}"><strong>${esc(r.name)}</strong><span>OC4 / NREL 5 MW <b class="status-${r.status}">${STATUS[r.status]}</b></span><small>${esc(new Date(r.created).toLocaleString('zh-CN'))}${Number.isFinite(r.elapsed_seconds)?' · '+fmt(r.elapsed_seconds,1)+' s':''}</small><div class="or-task-progress">${r.status==='completed'?'<i style="width:100%"></i>':Number.isFinite(r.progress)&&r.progress>0?`<i style="width:${Math.min(100,Math.max(0,r.progress))}%"></i>`:'<i class="indeterminate"></i>'}</div><em>${r.status==='completed'?'100%':r.progress>0?fmt(r.progress,1)+'%':r.status==='failed'||r.status==='cancelled'?'运行已结束':'等待引擎进度'}</em></button>${r.status==='completed'?`<label class="or-compare"><input type="checkbox" data-task-compare="${esc(r.id)}" ${state.comparison.includes(r.id)?'checked':''}> 加入对比</label>`:''}</article>`).join('')}</section>`;}).join('')||'<p class="ow-empty">没有匹配的运行记录。</p>';list.scrollTop=scroll;}
 list.onclick=e=>{const button=e.target.closest('[data-run]');if(button)workspaceSelect(button.dataset.run);};list.onchange=e=>{const id=e.target.dataset.taskCompare;if(!id)return;const ids=new Set(state.comparison);if(e.target.checked){if(ids.size>=4){e.target.checked=false;root.querySelector('.or-source-note').textContent='最多同时对比 4 个已完成工况。';return;}ids.add(id);}else ids.delete(id);workspaceCompare([...ids]);};
 root.querySelector('#or-task-search').oninput=e=>{taskQuery=e.target.value.toLowerCase();tasks();};
 function logs(){const record=state?.record,raw=record?.logs||[],counts={all:raw.length,info:0,warning:0,error:0};const classified=raw.map((line,i)=>{const severity=logLevel(line);counts[severity]++;return {line,i,severity};});root.querySelectorAll('[data-level]').forEach(button=>{const key=button.dataset.level;button.textContent=({all:'全部',info:'信息',warning:'警告',error:'错误'})[key]+` (${counts[key]})`;button.classList.toggle('active',key===level);button.setAttribute('aria-pressed',String(key===level));});const filtered=classified.filter(item=>(level==='all'||item.severity===level)&&item.line.toLowerCase().includes(query));const oldScroll=lines.scrollTop;lines.innerHTML=filtered.length?filtered.map(item=>`<div class="or-log-row ${item.severity}"><span>${String(item.i+1).padStart(4,'0')}</span><b>${item.severity==='error'?'ERROR':item.severity==='warning'?'WARN':'LOG'}</b><code>${esc(item.line)||' '}</code></div>`).join(''):`<p class="ow-empty">${raw.length?'没有符合筛选条件的日志。':esc(record?.error||'该记录尚未提供日志。')}</p>`;const stamp=record?.id+'|'+raw.length+'|'+raw.at(-1);if(follow&&stamp!==logStamp)lines.scrollTop=lines.scrollHeight;else lines.scrollTop=oldScroll;logStamp=stamp;root.querySelector('.or-log-footer').textContent=`显示 ${filtered.length} / ${raw.length} 行 · ${follow?'自动跟随已开启':'已暂停跟随，可自由浏览'} · 级别为界面辅助分类，原文保持不变`;}
 root.querySelectorAll('[data-level]').forEach(button=>button.onclick=()=>{level=button.dataset.level;logs();});root.querySelector('#or-log-search').oninput=e=>{query=e.target.value.toLowerCase();logs();};root.querySelector('#or-follow').onchange=e=>{follow=e.target.checked;if(follow)lines.scrollTop=lines.scrollHeight;logs();};
 root.querySelector('#or-import').onclick=()=>document.getElementById('import-run').click();root.querySelector('.or-backup').onclick=()=>document.getElementById('export-project').click();root.querySelector('#or-paste').onclick=()=>document.getElementById('paste-log-open').click();root.querySelector('#or-download').onclick=()=>document.getElementById('download-log').click();root.querySelector('#or-cancel').onclick=()=>{if(state.record?.id===state.active)document.getElementById('cancel-run').click();};root.querySelector('#or-results').onclick=()=>window.dispatchEvent(new CustomEvent('tideflow:navigate',{detail:'analysis'}));
 root.querySelectorAll('[data-file]').forEach(button=>button.onclick=()=>{const record=state?.record;if(!record)return;if(button.dataset.file==='input')document.getElementById('export-current').click();else if(button.dataset.file==='log')document.getElementById('download-log').click();else if(state.local&&record.artifacts?.output){const a=document.createElement('a');a.href=record.artifacts.output;a.download='OpenFAST.out';a.click();}else document.getElementById('export-csv').click();});
 function update(next){state=next;tasks();logs();const record=next.record,status=record?.status,complete=status==='completed',running=['preparing','running'].includes(status);root.querySelector('.or-service').innerHTML=`<i></i>${next.local?'本机引擎已连接':'真实算例浏览'}<small>OpenFAST 5.0.0</small>`;const current=status==='preparing'?0:status==='running'?2:complete?4:2;root.querySelector('.or-stages').innerHTML=['参数检查','生成输入','OpenFAST 求解','整理输出'].map((label,i)=>`<li class="${i<current?'done':i===current?'current':''} ${!complete&&!running&&i===current?'stopped':''}"><b>${i<current?'✓':i+1}</b><strong>${label}</strong><small>${i<current?'已完成':i===current?(running?'进行中':STATUS[status]||'等待任务'):'等待中'}</small></li>`).join('');root.querySelector('.or-progress-description').textContent=complete?'运行已完成，输出已通过格式校验。':running?(record.progress>0?`引擎日志进度 ${fmt(record.progress,1)}% · 已耗时 ${fmt(record.elapsed_seconds,1)} s`:'引擎正在初始化，等待真实日志进度。'):record?.error||'选择一条运行记录查看详细证据。';
 const params=record?.params,fields=params?[['任务名称',record.name],['参考模型','OC4 / NREL 5 MW'],['计算时长',params.duration+' s'],['分析起点',params.discard+' s'],['风速',params.wind+' m/s'],[params.wave_mode==='regular'?'波高 H':'显著波高 Hs',params.wave_height+' m'],[params.wave_mode==='regular'?'周期 T':'峰值周期 Tp',params.wave_period+' s'],['波浪类型',params.wave_mode==='regular'?'规则波':'JONSWAP'],['随机种子',params.wave_mode==='irregular'?String(params.seed):'规则波不使用'],['求解步长',params.solver_dt+' s']]:[];root.querySelector('.or-parameters').innerHTML=`<dl>${fields.map(([label,value])=>`<div><dt>${label}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl>`;root.querySelector('.or-findings').innerHTML=(record?.findings||[]).slice(0,3).map(f=>`<article class="${esc(f.severity)}"><strong>${esc(f.title)}</strong><p>${esc(f.advice)}</p></article>`).join('');root.querySelector('.or-source-note').textContent=record?source(record)+' · 日志来自当前记录，未生成演示进度。':'选择或导入一个真实工况。';root.querySelector('#or-results').disabled=!record?.result;root.querySelector('#or-cancel').disabled=!(running&&record?.id===next.active&&next.local);root.querySelector('#or-download').disabled=!record?.logs?.length;root.querySelector('[data-file=input]').disabled=!record;root.querySelector('[data-file=log]').disabled=!record?.logs?.length;root.querySelector('[data-file=output]').disabled=!record?.result;}
 new MutationObserver(()=>{if(document.body.dataset.page==='records'&&follow)requestAnimationFrame(()=>lines.scrollTop=lines.scrollHeight);}).observe(document.body,{attributes:true,attributeFilter:['data-page']});
 return {update};
}
